#!/usr/bin/env python3
"""Probe which PDF-related Python modules are available."""
import importlib

modules = [
    "pypdf", "PyPDF2", "reportlab", "pdfplumber", "fitz",
    "pdfrw", "pikepdf", "PIL", "pandas",
]
for name in modules:
    try:
        mod = importlib.import_module(name)
        version = getattr(mod, "__version__", "unknown")
        print(f"{name}: AVAILABLE (version={version})")
    except Exception as exc:
        print(f"{name}: NOT available ({type(exc).__name__}: {exc})")

#!/usr/bin/env python3
"""Probe for command-line PDF tools."""
import shutil
import subprocess

tools = ["qpdf", "pdftotext", "pdfinfo", "pdfunite", "pdftk", "gs", "mutool", "python3"]
for tool in tools:
    path = shutil.which(tool)
    if path is None:
        print(f"{tool}: NOT found")
        continue
    try:
        if tool == "python3":
            out = subprocess.run(
                [tool, "-c", "import sys; print(sys.version)"],
                capture_output=True, text=True, timeout=15,
            ).stdout.strip()
        else:
            out = subprocess.run(
                [tool, "--version"], capture_output=True, text=True, timeout=15,
            ).stdout.strip() or subprocess.run(
                [tool, "-v"], capture_output=True, text=True, timeout=15,
            ).stdout.strip() or subprocess.run(
                [tool, "-version"], capture_output=True, text=True, timeout=15,
            ).stdout.strip()
        print(f"{tool}: FOUND at {path} -> {out.splitlines()[0] if out else '(no version output)'}")
    except Exception as exc:
        print(f"{tool}: FOUND at {path} but version check failed ({exc})")

#!/usr/bin/env python3
"""Probe multiple python interpreters for PDF libraries."""
import subprocess

pythons = [
    "/mlx_devbox/users/zhengxinran/playground/code_zxr/agent_safety/active_defense/.tools/plant_agents_venv/bin/python",
    "/usr/bin/python3",
    "/home/tiger/miniconda3/bin/python",
]

modules = ["pypdf", "PyPDF2", "reportlab", "pdfplumber", "fitz", "pypdfium2", "PIL", "pdfrw", "pikepdf"]

probe_code = (
    "import importlib; "
    "mods = " + repr(modules) + "; "
    "print('|'.join(m + '=' + ('yes' if importlib.util.find_spec(m) else 'no') for m in mods))"
)

for py in pythons:
    try:
        out = subprocess.run(
            [py, "-c", probe_code],
            capture_output=True, text=True, timeout=30,
        )
        print(f"{py}:\n  stdout: {out.stdout.strip()}\n  stderr: {out.stderr.strip()[:300]}")
    except Exception as exc:
        print(f"{py}: ERROR {exc}")

